const (
    TokenLiveSite     Token = "{{live_site}}"
    TokenConfirmLink  Token = "{{confirm_link}}"
    TokenZipLink      Token = "{{zip_link}}"
    TokenInstructions Token = "{{instructions_link}}"  // bugs_open/475. Config KEY stays
                                                       // instructions_url: the estate pairs a
                                                       // *_url key with a *_link placeholder
                                                       // (domain_rent, domain_buy, stripe_portal).
    TokenDomainRent   Token = "{{domain_rent_link}}"
    TokenDomainBuy    Token = "{{domain_buy_link}}"
    TokenStripePortal Token = "{{stripe_portal_link}}"
    TokenDays         Token = "{{days}}"               // NOT a link. AdvertisedWindowDays.
)

var Vocabulary = []Token{ /* all of the above */ }

// Availability is what ONE SENDER says about ONE token on THIS dispatch.
// VALUES COME FROM THE CALLER: the same token resolves differently in different
// senders ({{live_site}} is config here and an input there; {{confirm_link}} is
// minted inside Claim here and post-claim there), so nothing about provenance
// belongs in the Vocabulary.
type Availability struct {
    Value       string // resolved by the caller; "" means this dispatch has none
    Source      string // where it should have come from, for the refusal text
    NeverReason string // non-empty: this sender can NEVER produce it, and why
}

type Fill map[Token]Availability

// Check refuses BEFORE the caller's irreversible statement. Order matters:
//  0. MALFORMED - Value AND NeverReason both set is a programming error, refused
//     outright rather than silently resolved. (NeverReason would win; a caller
//     that sets both is confused and should be told at once.)
//  1. UNKNOWN  - any {{...}} in the template absent from Vocabulary. This is what
//     moves an ahead-of-the-binary template's failure to BEFORE the stamp.
//  2. COVERAGE - every Vocabulary token must be declared by this Fill.
//  3. AVAILABILITY - a NAMED token with empty Value, or any NeverReason.
func (f Fill) Check(template string) error

// Apply substitutes from the SAME map Check read. That identity is the point.
// The caller's post-fill "{{" scan STAYS: coverage asks whether the vocabulary
// KNOWS a token, the scan asks whether Apply actually SUBSTITUTED it. A declared
// token that survives the fill is invisible to coverage by construction.
func (f Fill) Apply(template string) string

f := delivery.Fill{
    delivery.TokenLiveSite:     {Value: inputs.Get("live_site_url"), Source: "live_site_url input"},
    delivery.TokenDays:         {Value: fmt.Sprintf("%d", delivery.AdvertisedLiveWindowDays)},
    delivery.TokenConfirmLink:  {Value: mintedLater},  // always produced by Claim
    delivery.TokenZipLink:      {Value: zipPresign, Source: "zip_presigned_url"},
    delivery.TokenInstructions: {Value: stringOr(config, "instructions_url"),
                                 Source: "instructions_url config"},
    delivery.TokenDomainRent:   {Value: stringOr(config, "domain_rent_url"),
                                 Source: "domain_rent_url config"},
    ... // every Vocabulary token; omitting one is itself the refusal
}
if err := f.Check(bodyTemplate); err != nil {          // BEFORE delivery.Claim
    return nil, fmt.Errorf("delivery email refused before claim: %w", err)
}
// ... delivery.Claim stamps ...
body := f.Apply(bodyTemplate)
if i := strings.Index(body, "{{"); i >= 0 { /* UNCHANGED - see vocabulary.go */ }

func AssertCoversVocabulary(t *testing.T, f Fill)   // omission AND invention
func AssertNeverProduces(t *testing.T, f Fill, tok Token)

// order, not just coverage - sqlmock with NO expectations:
func TestCheckRefusesBeforeAnyDatabaseCall(t *testing.T) {
    db, mock, _ := sqlmock.New()            // no ExpectBegin, no ExpectQuery
    err := f.Check(templateNamingAnEmptyToken)
    require.Error(t, err)
    require.NoError(t, mock.ExpectationsWereMet())  // nothing touched the DB
}

